parameters.functionCode:
// Extract project info
const projectId = $json.projectId;
const projectName = $json.projectName;
const triggeredBy = $json.triggeredBy || 'manual';

return {
  json: {
    projectId,
    projectName,
    triggeredBy,
    startTime: new Date().toISOString()
  }
};

parameters.query:
SELECT id, project_name, system_brief, project_type, platforms, github_repo_url, target_branch
FROM e2e_projects
WHERE id = '{{ $json.projectId }}';

parameters.functionCode:
// Initialize shared context
const project = $('Load Project').first().json;
const requirements = $items().map(item => item.json);

const sharedContext = {
  project_overview: {
    name: project.project_name,
    brief: project.system_brief,
    type: project.project_type,
    platforms: project.platforms
  },
  functional_requirements: requirements.filter(r => r.requirement_type === 'functional'),
  non_functional_requirements: requirements.filter(r => r.requirement_type === 'non_functional'),
  constraints: requirements.filter(r => r.requirement_type === 'constraint'),
  compliance_requirements: [],
  business_constraints: [],
  ux_requirements: [],
  technology_decisions: [],
  architectural_patterns: [],
  infrastructure_constraints: [],
  identified_risks: [],
  key_assumptions: [],
  expert_recommendations: {},
  decision_rationale: {}
};

return {
  json: {
    projectId: project.id,
    projectName: project.project_name,
    githubRepo: project.github_repo_url,
    targetBranch: project.target_branch,
    sharedContext,
    contextVersion: 1
  }
};

parameters.query:
SELECT component_name, component_type, description, capabilities, constraints, example_usage
FROM oam_component_catalog
ORDER BY component_type, component_name;

parameters.functionCode:
const context = $('Initialize Shared Context').first().json.sharedContext;
const components = $items().map(item => item.json);

// Categorize components in single pass
const categorized = components.reduce((acc, c) => {
  acc[c.component_type] = acc[c.component_type] || [];
  acc[c.component_type].push(c);
  return acc;
}, {});

context.platform_capabilities = {
  available_components: components,
  foundational: categorized.foundational || [],
  compositional: categorized.compositional || [],
  infrastructural: categorized.infrastructural || []
};

return {
  json: {
    projectId: $('Initialize Shared Context').first().json.projectId,
    sharedContext: context,
    contextVersion: 2
  }
};

// Generate final PRD from all expert inputs
const projectName = $('Initialize Shared Context').first().json.projectName;
const finalContext = $json.updatedContext;
const timestamp = new Date().toISOString().split('T')[0];

// Helper function for bullet lists
const toBulletList = (arr) => (arr || []).map(item => `- ${typeof item === 'string' ? item : item.description || JSON.stringify(item)}`).join('\n') || '- None specified';

// Helper for risk formatting
const formatRisk = (risk, idx) => `### Risk ${idx + 1}: ${risk.description}\n**Severity**: ${risk.severity}\n**Mitigation**: ${risk.mitigation}`;

// PRD Template
const prd = `# Product Requirements Document: ${projectName}

**Generated**: ${new Date().toISOString()}
**Version**: 1.0

---

## 1. Project Overview

${finalContext.project_overview.brief}

**Project Type**: ${finalContext.project_overview.type}
**Target Platforms**: ${finalContext.project_overview.platforms.join(', ')}

---

## 2. Core Features

${finalContext.functional_requirements.map((req, idx) => `### ${idx + 1}. ${req.description}\n${req.acceptance_criteria ? `**Acceptance Criteria**:\n${req.acceptance_criteria.map(ac => `- ${ac}`).join('\n')}` : ''}`).join('\n\n')}

---

## 3. Business Architecture

${finalContext.expert_recommendations.business_architect || 'Pending business architecture analysis.'}

**Business Constraints**:
${toBulletList(finalContext.business_constraints)}

---

## 4. User Experience Requirements

${finalContext.expert_recommendations.experience_designer || 'Pending UX analysis.'}

**UX Requirements**:
${toBulletList(finalContext.ux_requirements)}

---

## 5. Technical Architecture

### 5.1 Strategic Technology Decisions

${finalContext.expert_recommendations.technology_cto || 'Pending CTO review.'}

**Technology Stack**:
${toBulletList(finalContext.technology_decisions)}

### 5.2 Application Architecture

${finalContext.expert_recommendations.application_architect || 'Pending application architecture design.'}

**Architectural Patterns**:
${toBulletList(finalContext.architectural_patterns)}

---

## 6. Compliance & Security

${finalContext.expert_recommendations.compliance_risk_assessor || 'Pending compliance review.'}

**Compliance Requirements**:
${toBulletList(finalContext.compliance_requirements)}

---

## 7. Infrastructure & Operations

${finalContext.expert_recommendations.infrastructure_reviewer || 'Pending infrastructure review.'}

**Infrastructure Constraints**:
${toBulletList(finalContext.infrastructure_constraints)}

---

## 8. Risks and Mitigations

${(finalContext.identified_risks || []).map(formatRisk).join('\n\n') || '- No critical risks identified'}

---

## 9. Logical Dependency Chain (OAM)

${finalContext.expert_recommendations.solution_architect || 'OAM definitions generated separately.'}

---

## 10. Development Roadmap

### Phase 1: Foundation (Weeks 1-4)
- Infrastructure setup
- Core services implementation
- Authentication & authorization

### Phase 2: Core Features (Weeks 5-8)
${finalContext.functional_requirements.slice(0, 3).map(r => `- ${r.description}`).join('\n')}

### Phase 3: Enhancement (Weeks 9-12)
${finalContext.functional_requirements.slice(3).map(r => `- ${r.description}`).join('\n')}

### Phase 4: Production Readiness (Weeks 13-16)
- Performance optimization
- Security hardening
- Documentation
- Deployment automation

---

## Appendices

### A. Source Requirements
- System Brief (Business Analyst)
- Functional Requirements (${finalContext.functional_requirements.length} requirements)
- Non-Functional Requirements (${finalContext.non_functional_requirements.length} requirements)

### B. Expert Consultations
- Compliance & Risk Assessor
- Business Architect
- Experience Designer
- Technology CTO
- Application Architect
- Solution Architect
- Infrastructure Reviewer

### C. Decision Rationale
${Object.entries(finalContext.decision_rationale).map(([key, value]) => `**${key}**: ${value}`).join('\n')}

---

*Generated by PRD Generator Orchestrator*
*Project ID: ${$('Initialize Shared Context').first().json.projectId}*
`;

return {
  json: {
    projectId: $('Initialize Shared Context').first().json.projectId,
    projectName,
    prdContent: prd,
    finalContext
  }
};

